<?php
declare(strict_types=1);
function student_form(array $data = [], array $errors = [], bool $editing = false): void {
    if ($errors) { ?><div class="form-error" role="alert"><strong>Periksa kembali isian berikut.</strong><ul><?php foreach ($errors as $key=>$message): ?><li><a href="#<?=e($key)?>"><?=e($message)?></a></li><?php endforeach ?></ul></div><?php }
    ?><form class="student-form" enctype="multipart/form-data" method="post" action="<?=$editing ? '/proses-edit.php' : '/proses-pendaftaran.php'?>"><?=csrf_field()?><?php if ($editing): ?><input type="hidden" name="id" value="<?=e($data['id'])?>"><?php endif ?><div class="form-section-title"><span>01</span><div><h2>Identitas calon siswa</h2><p>Semua kolom wajib diisi. Gunakan data rekaan.</p></div></div><div class="form-grid"><?php foreach (['nama'=>['Nama lengkap','Contoh: Alya Prameswari',64], 'sekolah_asal'=>['Sekolah asal','Contoh: SMP Negeri 1 Surabaya',64]] as $key=>[$label,$placeholder,$max]): ?><div class="field"><label for="<?=$key?>"><?=$label?> <span>*</span></label><input id="<?=$key?>" name="<?=$key?>" required minlength="2" maxlength="<?=$max?>" value="<?=e($data[$key] ?? '')?>" placeholder="<?=$placeholder?>" <?=isset($errors[$key]) ? 'aria-invalid="true" aria-describedby="error-'.$key.'"' : ''?>><?php if (isset($errors[$key])): ?><small class="field-error" id="error-<?=$key?>"><?=e($errors[$key])?></small><?php endif ?></div><?php endforeach ?><div class="field"><label for="jenis_kelamin">Jenis kelamin <span>*</span></label><select id="jenis_kelamin" name="jenis_kelamin" required <?=isset($errors['jenis_kelamin']) ? 'aria-invalid="true" aria-describedby="error-jenis_kelamin"' : ''?>><option value="">Pilih jenis kelamin</option><?php foreach (GENDERS as $g): ?><option <?=($data['jenis_kelamin'] ?? '') === $g ? 'selected' : ''?>><?=e($g)?></option><?php endforeach ?></select><?php if (isset($errors['jenis_kelamin'])): ?><small class="field-error" id="error-jenis_kelamin"><?=e($errors['jenis_kelamin'])?></small><?php endif ?></div><div class="field"><label for="agama">Agama <span>*</span></label><select id="agama" name="agama" required <?=isset($errors['agama']) ? 'aria-invalid="true" aria-describedby="error-agama"' : ''?>><option value="">Pilih agama</option><?php foreach (RELIGIONS as $r): ?><option <?=($data['agama'] ?? '') === $r ? 'selected' : ''?>><?=e($r)?></option><?php endforeach ?></select><?php if (isset($errors['agama'])): ?><small class="field-error" id="error-agama"><?=e($errors['agama'])?></small><?php endif ?></div><div class="field full"><label for="alamat">Alamat lengkap <span>*</span></label><textarea id="alamat" name="alamat" required minlength="5" maxlength="255" rows="4" placeholder="Nama jalan, nomor, dan kota" <?=isset($errors['alamat']) ? 'aria-invalid="true" aria-describedby="error-alamat"' : ''?>><?=e($data['alamat'] ?? '')?></textarea><?php if (isset($errors['alamat'])): ?><small class="field-error" id="error-alamat"><?=e($errors['alamat'])?></small><?php else: ?><small>Maksimal 255 karakter.</small><?php endif ?></div></div><?php photo_field($data, $errors, $editing); ?><div class="form-actions"><a class="button secondary" href="<?=$editing ? '/detail.php?id='.(int)$data['id'] : '/list-siswa.php'?>">Batal</a><button class="button" type="submit"><?=icon('check')?> <?=$editing ? 'Simpan perubahan' : 'Simpan pendaftaran'?></button></div></form><?php
}
function form_page(array $data = [], array $errors = [], bool $editing = false): void {
    page_start($editing ? 'Edit siswa' : 'Tambah siswa',$editing ? 'siswa' : 'daftar');
    heading('FORMULIR PENDAFTARAN', $editing ? 'Perbarui data, tetap tertata.' : 'Satu formulir, awal cerita baru.', $editing ? 'Sesuaikan informasi calon siswa lalu simpan perubahan.' : 'Lengkapi informasi berikut untuk mendaftarkan calon siswa.');
    ?><div class="form-layout"><section class="panel form-panel"><?php student_form($data,$errors,$editing); ?></section><aside class="form-aside"><div class="panel advice"><span class="stat-icon green"><?=icon('school')?></span><h2>Mulai dengan<br>data yang tepat.</h2><p>Periksa kembali nama, sekolah asal, dan alamat sebelum menyimpan formulir.</p><div class="advice-item"><?=icon('check')?> Identitas dan pas foto 3 x 4</div><div class="advice-item"><?=icon('check')?> Bisa diperbarui kapan saja</div><div class="advice-item"><?=icon('check')?> Tersimpan di ruang demo Anda</div><hr><small>Pendaftaran ini untuk simulasi PPDB. Tidak ada proses seleksi atau penerimaan siswa nyata.</small></div><a class="text-link" href="/panduan.php">Perlu bantuan? Baca panduan <?=icon('arrow')?></a></aside></div><?php page_end();
}
